#ifndef V8_EXPERIMENTAL_REDLINE_GENERATORS_GENERATOR_H_
#define V8_EXPERIMENTAL_REDLINE_GENERATORS_GENERATOR_H_

#include <memory>
#include <string>
#include <string_view>
#include <vector>

#include "experimental/redline/core/builder.h"
#include "experimental/redline/core/component.h"
#include "experimental/redline/core/environment.h"
#include "experimental/redline/core/selection.h"

namespace redline {

class GeneratorSet;

// Everything a generator needs to know about the place it generates code
// for. Generated statements are collected by the caller and inserted at
// `slot` in one go; `visible` is extended by generators that declare new
// variables so that later generators in the same session can use them.
struct GenContext {
  GenContext(Builder& b, const GeneratorSet& g, const Environment& e)
      : builder(b), generators(g), env(e) {}

  Builder& builder;
  const GeneratorSet& generators;
  const Environment& env;
  Builder::Slot slot;
  Builder::Context syntax;
  std::vector<Variable> visible;  // innermost first
  int depth = 0;                  // nesting depth of generated code
  int max_depth = 3;
  // Statements generated by this session so far (for generators that want
  // to refer to something they just created).
  std::vector<fast::Statement*>* out = nullptr;

  fast::Tree* tree() { return builder.tree(); }
  Random& rng() { return builder.rng(); }

  // Registers a variable created by generated code.
  void Declare(std::string_view name, JsType type, bool is_constant = false) {
    visible.insert(visible.begin(), Variable{name, type, nullptr, is_constant});
  }
  // A context for code nested inside a function-like node generated at
  // this position.
  GenContext Nested(bool is_function, bool is_arrow, bool is_async,
                    bool is_generator) const;
  // A context for a loop/switch/block body at this position.
  GenContext Inner(bool in_loop, bool in_switch) const;
};

// Requirements a generator has on the syntactic context.
enum GenRequirement : uint32_t {
  kNoRequirement = 0,
  kNeedsFunction = 1u << 0,   // emits `return`
  kNeedsAsync = 1u << 1,      // emits `await`
  kNeedsGenerator = 1u << 2,  // emits `yield`
  kNeedsLoop = 1u << 3,       // emits `continue`
  kNeedsBreak = 1u << 4,      // emits `break`
  kNeedsSloppy = 1u << 5,     // emits sloppy-only syntax (`with`)
  kNeedsArguments = 1u << 6,  // uses `arguments`
  kNeedsThis = 1u << 7,       // uses `this` meaningfully
  kRecursive = 1u << 8,       // generates nested code (depth-limited)
};

class Generator : public Component {
 public:
  Generator(std::string name, std::string_view description, double weight,
            uint32_t requirements)
      : Component(std::move(name)),
        description_(description),
        weight_(weight),
        requirements_(requirements) {}

  std::string_view description() const override { return description_; }
  double weight() const { return weight_; }
  uint32_t requirements() const { return requirements_; }
  bool Applicable(const GenContext& ctx) const;

  // Appends zero or more statements to `out`. Returns false if nothing
  // suitable could be generated here.
  virtual bool Generate(GenContext& ctx,
                        std::vector<fast::Statement*>* out) = 0;

 private:
  std::string_view description_;
  double weight_;
  uint32_t requirements_;
};

// All generators, and the strategy that picks among them (core/selection.h).
// CreateDefault() installs the built-in generators with the default
// `weighted` strategy; a fuzzing session replaces the strategy with the
// configured one through SetSelector().
class GeneratorSet {
 public:
  // All built-in generators with default weights.
  static std::unique_ptr<GeneratorSet> CreateDefault();

  const std::vector<std::unique_ptr<Generator>>& all() const {
    return generators_;
  }
  // The same generators as plain pointers, in the same order: what the
  // selector sees.
  const std::vector<Generator*>& candidates() const { return candidates_; }
  Generator* Find(std::string_view name) const;
  std::vector<std::string> Names() const;

  // Installs a selection strategy and initializes it with the generators
  // (weight names are validated here). Returns false with *error set.
  bool SetSelector(std::unique_ptr<Selector<Generator>> selector,
                   std::string* error);
  Selector<Generator>& selector() const { return *selector_; }
  // Shorthands for the strategy's static weights (0 disables a generator).
  bool SetWeight(std::string_view name, double weight) {
    return selector_->SetWeight(name, weight);
  }
  double WeightOf(const Generator* generator) const {
    return selector_->WeightOf(*generator);
  }

  // Picks an applicable generator with the strategy, or nullptr.
  Generator* Pick(const GenContext& ctx) const;
  // Generates roughly `count` statements at ctx.slot, appending them to
  // `out`. Returns the number of generator invocations that produced code.
  int Generate(GenContext& ctx, int count,
               std::vector<fast::Statement*>* out) const;

  std::vector<const Component*> Components() const;

 private:
  std::vector<std::unique_ptr<Generator>> generators_;
  std::vector<Generator*> candidates_;
  std::unique_ptr<Selector<Generator>> selector_;
};

// A generation context for inserting statements at `slot`: syntactic
// context and visible variables are computed from the builder.
GenContext MakeGenContext(Builder& builder, const Builder::Slot& slot,
                          const GeneratorSet& generators,
                          const Environment& env);

// The generators that produced output on this thread since the last
// BeginGeneratorUsage() (deduplicated). The engine credits them with the
// execution of the mutation result and with its coverage, which feeds the
// "adaptive" generator strategy.
void BeginGeneratorUsage();
void NoteGeneratorUsed(Generator* generator);
std::vector<Generator*> GeneratorsUsed();

}  // namespace redline

#endif  // V8_EXPERIMENTAL_REDLINE_GENERATORS_GENERATOR_H_
